# kubejs_tooltip_lmtranslator.py# ---------------------------------"""?詨??璁汗?箸?寥?蝧餉陌 (translate_batch_smart)嚗?典翰???嗅?蕃霅舀?蝔??踹???蝧餉陌?詨???摮?蝭??API 瘨?擃翰??瞈?(fast_split_items_by_cache)嚗蝧餉陌?翰??撠?翰??撠歇蝧餉陌????蝧餉陌????嚗???????摰敺芰蝧餉陌 (translate_items_with_cache_loop)嚗??瑕? ETA嚗?閮擗??? 憿舐內???∠ 摰??嚗afe Slicing嚗??銵??脫迫?甈∟?瘙?憭批??游仃???琿?蝥??摮?雿輻 TouchSet ??Writer Flush 璈嚗蕃霅舫?蝔葉??神?交?獢??喃蝙蝔???銝剜銋??憭勗歇摰??脣漲???炎璅∪? (dry_run)嚗?湔芋?砍銵蒂頛詨?汗瑼?嚗rite_dry_run_preview嚗?霈??冽迤撘???API 憿漲?Ⅱ隤撘?行迤蝣箝??豢?撠 (TranslationRecorder)嚗?游?蝧餉陌閮?撠??JSON ??CSV ?澆?嚗靘踹?蝥撠?鈭活????脣漲餈質馱 (session.set_progress)嚗撱粹脣漲?文?嚗ook嚗??臬??亙???UI ?隤頂蝯梢＊蝷箇蕃霅舐????頝臬??芸?嚗????蝟餉??冗頧?嚗?憒????en_us ?芸?撠???zh_tw ?桅?嚗?Rich Text Shield嚗hield_text() / unshield_text() 靽風 KubeJS ?澆?嚗蔗?脩Ⅳ??D?RL 蝑?嚗??函蕃霅臬??賢嚗蕃霅臬???嚗??LM 隤斤蕃?澆?璅???"""from __future__ import annotationsfrom dataclasses import dataclassfrom pathlib import Pathfrom typing import Dict, Any, List, Optional, Tuplefrom concurrent.futures import ThreadPoolExecutor, as_completedimport reimport openccfrom translation_tool.core.lm_translator_main import translate_batch_smartfrom translation_tool.core.lm_config_rules import validate_api_keysfrom translation_tool.utils.config_manager import load_configfrom translation_tool.core.lm_translator_shared import (    CacheRule,    fast_split_items_by_cache,    translate_items_with_cache_loop,    TouchSet,    TranslationRecorder,    write_dry_run_preview,    write_cache_hit_preview,  # ???啣?嚗ache hit preview 瑼?    _is_valid_hit,  # ???啣?嚗ache hit ?斗)from translation_tool.plugins.shared.json_io import (    read_json_dict,    write_json_dict,    collect_json_files,)from translation_tool.plugins.shared.lang_path_rules import (    compute_output_path,)from translation_tool.plugins.shared.rich_text_shield import (    shield_text,    unshield_text,)from translation_tool.utils.log_unit import log_info, log_warning, progress# -------------------------# Smart item mapping# -------------------------def collect_items_from_mapping(    mapping: Dict[str, Any],    *,    file_hint: str,) -> List[Dict[str, Any]]:    """    撠?{頝臬??? ??} ??撠??蝧餉陌?寞活???    ?蝣箔??箸?菜葫?質???KubeJS ?蔭嚗tem["file"] ? "/kubejs/"嚗?    Shield ?游?嚗?瘥???銝脣澆銵?shield_text()嚗?    - ??skip_reason ??None嚗???URL/鈭辣蝑?嚗?乩?????蝧餉陌??    - ?仿?閬蕃霅荔???shield ??銋暹楊??嚗lean嚗?隞??????    - ????item 摮銝剝???_shielded嚗? on_translated_item() ??unshield ?‵??    """    items: List[Dict[str, Any]] = []    for k, v in mapping.items():        if not isinstance(k, str):            continue        if not isinstance(v, str) or not v.strip():            continue        # ??Rich Text Shield嚗?箔??蕃霅舐??澆??挾        shielded = shield_text(v)        if shielded.skip_reason is not None:            # 銝?蝧餉陌嚗???URL/鈭辣/蝛箇嚗??湔撖怠??銝?蝧餉陌蝞∠?            items.append(                {                    "file": file_hint,                    "path": k,                    "source_text": v,                    "text": v,  # 靽???                    "cache_type": "kubejs",                    "_shielded": shielded,  # 靘?unshield ?嚗迨???⊿???嚗?                    "_skip_reason": shielded.skip_reason,                }            )        else:            # ?閬蕃霅荔?雿輻 shield ??銋暹楊??            items.append(                {                    "file": file_hint,                    "path": k,                    "source_text": v,                    "text": shielded.clean,  # ??雿輻 shield ????靘蕃霅?                    "cache_type": "kubejs",                    "_shielded": shielded,  # 靘?on_translated_item() ??unshield                }            )    return itemsdef count_translatable_keys(mapping: Dict[str, Any]) -> int:    """閮? mapping 銝准蝧餉陌摮葡???賊???    ?斗璇辣嚗?    - value ?臬?銝?    - ?駁蝛箇敺??摰?    ?券?憿舐內?脣漲 / 隡啁?蝧餉陌蝮賡???    """    return sum(1 for _, v in mapping.items() if isinstance(v, str) and v.strip())# -------------------------# 蝜?銝剜??菜葫嚗?潸歲?歇蝧餉陌??tooltips嚗?# -------------------------_TW_CJK_RE = re.compile(r"[\u4e00-\u9fff]")_TW_CONVERTER = opencc.OpenCC("s2tw")def _is_tw_text(text: str) -> bool:    """?斗???臬撌脩??舐?擃葉??OpenCC 頧?敺?霈?= 撌脫蝜?嚗?""    if not text or not isinstance(text, str):        return False    if not _TW_CJK_RE.search(text):        return False  # ??CJK 摮?嚗??臭葉??    # 蝪⊿???擃???嚗????澆??祉??潘?隞?”?撠望蝜?    return _TW_CONVERTER.convert(text) == textdef _split_off_tw_items(    cached_items: List[Dict[str, Any]],    items_to_translate: List[Dict[str, Any]],) -> List[Dict[str, Any]]:    """敺?items_to_translate 蝘餃撌脩蕃霅荔?蝜?嚗????cached_items嚗??唾◤蝘餃???items??""    tw_items: List[Dict[str, Any]] = []    remaining: List[Dict[str, Any]] = []    for it in items_to_translate:        src_text = it.get("source_text", "") or ""        if _is_tw_text(src_text):            tw_items.append(it)        else:            remaining.append(it)    cached_items.extend(tw_items)    # 皜??蒂撖怠??拚?嚗n-place 靽格銝脣?嚗?    items_to_translate.clear()    items_to_translate.extend(remaining)    return tw_items# -------------------------# Dry-run stats (optional)# -------------------------@dataclassclass DryRunStats:    """DryRunStats 憿??    ?券?撠???DryRunStats ?賊?????銵??    蝬剛風瘜冽?嚗耨?孵?瘜?隢Ⅱ隤??典?恍??摰寞扼?    """    files: int = 0    total_keys: int = 0    cache_hit: int = 0    cache_miss: int = 0    per_file: Optional[list[dict]] = None# -------------------------# Public API (for UI/pipeline)# -------------------------def translate_kubejs_pending_to_zh_tw(    *,    pending_dir: str | Path,    output_dir: str | Path,    session=None,    rename_langs: Optional[set[str]] = None,    dry_run: bool = False,    write_new_cache: bool = False,) -> dict:    """    Translate KubeJS pending JSON dir -> output dir (usually LM蝧餉陌敺?.    - pending_dir: 靘? Output/kubejs/敺蕃霅?    - output_dir : 靘? Output/kubejs/LM蝧餉陌敺?    """    validate_api_keys()    in_dir = Path(pending_dir).resolve()    out_dir = Path(output_dir).resolve()    out_dir.mkdir(parents=True, exist_ok=True)    if rename_langs is None:        rename_langs = {            "ru_ru",            "ja_jp",            "ko_kr",            "zh_cn",            "zh_hk",            "zh_sg",            "pt_br",            "es_es",            "en_us",            "fr_fr",            "de_de",            "it_it",            "pl_pl",            "tr_tr",            "uk_ua",            "cs_cz",            "hu_hu",            "nl_nl",            "sv_se",            "no_no",            "da_dk",            "fi_fi",        }    if not in_dir.exists() or not in_dir.is_dir():        raise FileNotFoundError(f"pending_dir 銝??冽?銝鞈?憭橘?{in_dir}")    json_files = collect_json_files(in_dir)    if not json_files:        raise FileNotFoundError(f"?曆??唬遙雿?.json嚗in_dir}")    # -------------------------    # Pre-scan global total (multithread, like FTB)    # -------------------------    per_file_counts: List[Tuple[Path, int]] = []    global_total_keys = 0    # ??Issue #7b 靽桀儔嚗楨摮?JSON mapping ?踹???霈??    src_mapping_cache: Dict[Path, Dict[str, Any]] = {}    def _count_one(src: Path) -> Tuple[Path, int, Dict[str, Any]]:        """蝯梯??桐?瑼??蕃霅?key ?賊?嚗??翰??mapping??""        try:            mapping = read_json_dict(src)            return src, int(count_translatable_keys(mapping)), mapping        except Exception:            return src, 0, {}    max_workers = int(        load_config().get("translator", {}).get("parallel_execution_workers", 4) or 4    )    max_workers = max(1, max_workers)    with ThreadPoolExecutor(max_workers=max_workers) as ex:        futs = [ex.submit(_count_one, p) for p in json_files]        for fu in as_completed(futs):            src, c, mapping = fu.result()            per_file_counts.append((src, c))            global_total_keys += c            if mapping:  # ???芰楨摮?蝛箇? mapping                src_mapping_cache[src] = mapping    per_file_counts.sort(key=lambda x: x[0].as_posix())    if global_total_keys == 0:        log_info("?對? [KubeJS-LM] 0 keys嚗歲?蕃霅?)        return {"written_files": 0, "total_keys": 0, "out_dir": str(out_dir)}    # -------------------------    # Cache rules    # -------------------------    cache_rules = {"kubejs": CacheRule("path|source_text")}    # -------------------------    # Pre-calc global miss/hit (so progress uses "real translate count")    # -------------------------    global_total_to_translate = 0    global_total_hit = 0    for src, key_count in per_file_counts:        if key_count == 0:            continue        try:            # ??Issue #7b 靽桀儔嚗?乩蝙?函楨摮? mapping嚗???銴???            mapping = src_mapping_cache.get(src, {})            if not mapping:                continue            rel_src = src.relative_to(in_dir).as_posix()            file_hint = f"output/kubejs/{rel_src}"  # must contain /kubejs/            all_items = collect_items_from_mapping(mapping, file_hint=file_hint)            cached_items, items_to_translate = fast_split_items_by_cache(                all_items,                cache_rules=cache_rules,                is_valid_hit=_is_valid_hit,            )            # ??頝喲??澆歇蝬蝜?銝剜???items嚗???API + ?踹?蝪⊿??嗉?蕃嚗?            _split_off_tw_items(cached_items, items_to_translate)            global_total_hit += len(cached_items)            global_total_to_translate += len(items_to_translate)        except Exception:            pass    log_info(        f"?? [KubeJS-LM] 敺蕃霅舀?獢嚗len(json_files)}嚗蜇 keys嚗global_total_keys}\n"        f"??[KubeJS-LM] cache_hit={global_total_hit} | 撖阡??蝧餉陌(cache_miss)={global_total_to_translate}"    )    if global_total_to_translate == 0:        progress(1.0)    # -------------------------    # Global build + translate (NO per-file translate)    # -------------------------    translated_done = 0    avg_batch_sec = None    total_written = 0    per_file_rows: list[dict] = []    rec = TranslationRecorder()    touch = TouchSet()    _file_write_table: dict[str, tuple[Path, Dict[str, str]]] = {}    def _writer(file_id: str) -> None:        """撖怠蝧餉陌蝯??唳?獢?""        dst_path, data = _file_write_table[file_id]        write_json_dict(dst_path, data)    # Build phase: per-file state + global miss list    file_states: dict[str, dict] = {}    all_miss_items: List[Dict[str, Any]] = []    all_hit_items: List[Dict[str, Any]] = []    for idx, (src, key_count) in enumerate(per_file_counts, start=1):        if key_count == 0:            continue        # ??Issue #7b 靽桀儔嚗?乩蝙?函楨摮? mapping嚗???銴???        mapping = src_mapping_cache.get(src, {})        if not mapping:            continue        rel_src = src.relative_to(in_dir).as_posix()        file_hint = f"output/kubejs/{rel_src}"        all_items = collect_items_from_mapping(mapping, file_hint=file_hint)        cached_items, items_to_translate = fast_split_items_by_cache(            all_items,            cache_rules=cache_rules,            is_valid_hit=_is_valid_hit,        )        # ??頝喲??澆歇蝬蝜?銝剜???items嚗?蝧餉陌皜蝘餉 cache hit嚗?        _split_off_tw_items(cached_items, items_to_translate)        # ??NEW嚗敞蝛?hit items        all_hit_items.extend(cached_items)        hit = len(cached_items)        miss = len(items_to_translate)        dst = compute_output_path(src, in_dir, out_dir, rename_langs)        per_file_rows.append(            {                "file": rel_src,                "keys": key_count,                "cache_hit": hit,                "cache_miss": miss,                "dst": dst.relative_to(out_dir).as_posix(),            }        )        log_info(            f"[KubeJS-LM] 瑼? {idx}/{len(per_file_counts)}嚗rel_src} 嚚?            f"蝮賢?銝?{key_count}嚗翰?銝?{hit}嚗?蝧餉陌 {miss} 嚚?            f"頛詨 ??{dst.relative_to(out_dir).as_posix()}"        )        # out_map base        out_map: Dict[str, str] = {            k: v            for k, v in mapping.items()            if isinstance(k, str) and isinstance(v, str)        }        # apply cache hits now (record as hit)        for it in cached_items:            p = it.get("path")            t = it.get("text")            if isinstance(p, str) and isinstance(t, str):                out_map[p] = t                try:                    rec.record(                        cache_type="kubejs",                        file_id=rel_src,                        path=p,                        src=str(it.get("source_text") or ""),                        dst=t,                        cache_hit=True,                        extra={"dst_file": dst.relative_to(out_dir).as_posix()},                    )                except Exception:                    pass        file_id = dst.as_posix()        _file_write_table[file_id] = (dst, out_map)        file_states[rel_src] = {            "rel_src": rel_src,            "dst": dst,            "file_id": file_id,            "out_map": out_map,        }        # tag miss items with file context (so callback can write back to correct out_map)        for it in items_to_translate:            it["file_rel"] = rel_src            it["dst_file"] = dst.relative_to(out_dir).as_posix()        all_miss_items.extend(items_to_translate)    # -------------------------    # Dry-run: preview only (no API)    # -------------------------    if dry_run:        dry_preview_items = all_miss_items[:2000] if all_miss_items else []        preview_path = None        try:            meta = {                "files": len(per_file_rows),                "total_keys": global_total_keys,                "cache_hit": global_total_hit,                "cache_miss": global_total_to_translate,            }            preview_path = write_dry_run_preview(                out_dir,                dry_preview_items,                filename="_kubejs_dry_run_preview.json",                meta=meta,            )            log_info(f"?妒 [DRY-RUN] preview written: {preview_path.as_posix()}")            # ??NEW嚗ache hit preview            hit_preview_path = write_cache_hit_preview(                out_dir,                all_hit_items[:2000],  # ????                filename="_kubejs_dry_run_cache_hit_preview.json",                meta=meta,            )            log_info(                f"? [DRY-RUN] cache-hit preview written: {hit_preview_path.as_posix()}"            )        except Exception as e:            log_warning(f"?? [KubeJS-LM] DRY-RUN preview 頛詨憭望?嚗e}")        progress(1.0)        return {            "dry_run": True,            "files": len(per_file_rows),            "total_keys": global_total_keys,            "cache_hit": global_total_hit,            "cache_miss": global_total_to_translate,            "preview_path": str(preview_path) if preview_path else None,            "out_dir": str(out_dir),            "per_file": per_file_rows,        }    # -------------------------    # Real run: translate ONCE for all miss items    # -------------------------    if not all_miss_items:        # All cache hit -> flush all files once        for st in file_states.values():            touch.touch(st["file_id"])        touch.flush(_writer)        total_written = len(file_states)        translated_done = 0        progress(1.0)    else:        def on_translated_item(it: Dict[str, Any]) -> None:            """??蝧餉陌蝯???""            rel_src = it.get("file_rel")            p = it.get("path")            t = it.get("text")            s = it.get("source_text")            if not (isinstance(rel_src, str) and rel_src in file_states):                return            if not (isinstance(p, str) and isinstance(t, str)):                return            # ??Rich Text Shield嚗蕃霅臬???鋡思?霅瑞??澆??挾            shielded = it.get("_shielded")            if shielded is not None and shielded.shields:                final_text = unshield_text(t, shielded.shields)            else:                final_text = t            st = file_states[rel_src]            st["out_map"][p] = final_text            try:                rec.record(                    cache_type="kubejs",                    file_id=rel_src,                    path=p,                    src=str(s or ""),                    dst=t,                    cache_hit=False,                    extra={"dst_file": st["dst"].relative_to(out_dir).as_posix()},                )            except Exception:                pass            try:                touch.touch(st["file_id"])            except Exception:                pass        def on_batch_flushed() -> None:            # write touched files each batch            """?寥?撖怠蝧餉陌蝯???""            try:                touch.flush(_writer)            except Exception:                # fallback: write all                for fid, (dstp, data) in _file_write_table.items():                    write_json_dict(dstp, data)        def _fmt_eta(sec: float) -> str:            """?澆??擗???""            if sec <= 0:                return ""            m, s = divmod(int(sec), 60)            if m >= 60:                h, m2 = divmod(m, 60)                return f"{h}h{m2:02d}m{s:02d}s"            if m > 0:                return f"{m}m{s:02d}s"            return f"{s}s"        def on_progress(p: float, msg: str, eta_sec: float) -> None:            """?勗?蝧餉陌?脣漲??""            eta_txt = _fmt_eta(eta_sec)            log_info(f"{msg}" + (f" | ETA ??{eta_txt}" if eta_txt else ""))            progress(p)        res = translate_items_with_cache_loop(            all_miss_items,            total_for_smart=global_total_to_translate,            translate_batch_smart=lambda batch, total: translate_batch_smart(                batch, total=total            ),            write_new_cache=bool(write_new_cache),            cache_rules=cache_rules,            on_translated_item=on_translated_item,            on_batch_flushed=on_batch_flushed,            on_progress=on_progress,        )        translated_done = int(res.processed or 0)        avg_batch_sec = (            (res.elapsed_sec / res.completed_calls) if res.completed_calls else None        )        # final flush all        for st in file_states.values():            touch.touch(st["file_id"])        touch.flush(_writer)        total_written = len(file_states)        progress(1.0)    # -------------------------    # Export records    # -------------------------    rec_json = None    rec_csv = None    try:        rec_json = rec.export_json(out_dir / "translation_map.json")        rec_csv = rec.export_csv(out_dir / "translation_map.csv")        log_info(f"?屁 [KubeJS-LM] records written: {rec_json} | {rec_csv}")    except Exception as ex:        log_info(f"?? [KubeJS-LM] export records failed: {ex}")    return {        "written_files": total_written,        "total_keys": global_total_keys,        "cache_hit": global_total_hit,        "cache_miss": global_total_to_translate,        "api_translated": translated_done,        "avg_batch_sec": avg_batch_sec,        "out_dir": str(out_dir),        "records_json": str(rec_json) if rec_json else None,        "records_csv": str(rec_csv) if rec_csv else None,        "per_file": per_file_rows,    }